<div class="row g-3"><div class="col-lg-5"><div class="card-panel"><h3 class="h6">Import CSV / Excel-compatible</h3><p class="text-secondary">Download template, isi di Excel/Google Sheets, simpan sebagai CSV UTF-8, lalu preview sebelum commit.</p><div class="d-flex flex-wrap gap-2 mb-3"><a class="btn btn-sm btn-outline-secondary" href="<?= url('/import/template/customers') ?>">Customer Template</a><a class="btn btn-sm btn-outline-secondary" href="<?= url('/import/template/items') ?>">Item Template</a><a class="btn btn-sm btn-outline-secondary" href="<?= url('/import/template/assets') ?>">Asset Template</a></div><form method="post" enctype="multipart/form-data" action="<?= url('/import/preview') ?>"><?= csrf_field() ?><label class="form-label">Data Type</label><select class="form-select mb-2" name="type"><option value="customers">Customers</option><option value="items">Items</option><option value="assets">Assets</option></select><input class="form-control mb-3" type="file" accept=".csv,text/csv" name="file" required><button class="btn btn-primary w-100">Preview Import</button></form></div></div><div class="col-lg-7"><div class="card-panel"><h3 class="h6">Preview</h3><?php if(!$preview): ?><div class="empty-state">No import preview.</div><?php else: ?><div class="alert <?= $preview['errors']?'alert-warning':'alert-success' ?>"><?= count($preview['rows']) ?> rows ready. <?= count($preview['errors']) ?> structural error(s).</div><?php foreach($preview['errors'] as $e): ?><small class="d-block text-danger"><?= e($e) ?></small><?php endforeach; ?><div class="table-responsive mt-2" style="max-height:360px"><table class="table table-sm"><thead><tr><?php foreach($preview['headers'] as $h): ?><th><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach(array_slice($preview['rows'],0,50) as $r): ?><tr><?php foreach($preview['headers'] as $h): ?><td><?= e($r[$h]??'') ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><form class="ajax-form mt-3" method="post" action="<?= url('/import/commit') ?>"><?= csrf_field() ?><button class="btn btn-success">Commit <?= count($preview['rows']) ?> Rows</button></form><?php endif; ?></div></div></div>
